import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from "recharts";

const COLORS = ["#2563eb", "#7c3aed", "#059669", "#d97706", "#dc2626", "#0891b2"];

const Stat = ({ label, value, sub, accent }) => (
  <div style={{
    padding: "20px 24px", borderRadius: 10, border: "1px solid",
    borderColor: accent ? "#bfdbfe" : "#e8e8e6",
    background: accent ? "#eff6ff" : "#fafaf9",
  }}>
    <div style={{ fontSize: 12, color: accent ? "#3b82f6" : "#9b9b9b", fontWeight: 500, marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.06em" }}>{label}</div>
    <div style={{ fontSize: 24, fontWeight: 700, color: accent ? "#1d4ed8" : "#191919", letterSpacing: "-0.02em", lineHeight: 1 }}>{value}</div>
    {sub && <div style={{ fontSize: 12, color: "#9b9b9b", marginTop: 6 }}>{sub}</div>}
  </div>
);

const Card = ({ title, sub, children }) => (
  <div style={{ background: "#fff", border: "1px solid #e8e8e6", borderRadius: 10, padding: "24px", overflow: "hidden" }}>
    <div style={{ marginBottom: 20 }}>
      <div style={{ fontSize: 15, fontWeight: 600, color: "#191919" }}>{title}</div>
      {sub && <div style={{ fontSize: 12, color: "#9b9b9b", marginTop: 3 }}>{sub}</div>}
    </div>
    {children}
  </div>
);

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background: "#fff", border: "1px solid #e8e8e6", borderRadius: 8, padding: "10px 14px", fontSize: 13, boxShadow: "0 4px 12px rgba(0,0,0,0.08)" }}>
      <div style={{ color: "#6b6b6b", marginBottom: 4 }}>{label || payload[0]?.name}</div>
      <div style={{ fontWeight: 600, color: "#191919" }}>RM {Number(payload[0]?.value || 0).toFixed(2)}</div>
    </div>
  );
};

const Dashboard = () => {
  const [budgets, setBudgets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedMonth, setSelectedMonth] = useState(null);
  const name = localStorage.getItem("name") || "there";

  useEffect(() => {
    const userId = localStorage.getItem("userId");
    if (!userId) return;
    axios.get("/api/budgets", { params: { userId } })
      .then(r => setBudgets(Array.isArray(r.data) ? r.data : []))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const allExpenses = budgets.flatMap(b =>
    (b.expenses || []).map(e => ({ ...e, budgetName: b.name, budgetIcon: b.icon }))
  );

  const totalSpent = allExpenses.reduce((s, e) => s + (e.amount || 0), 0);
  const totalBudget = budgets.reduce((s, b) => s + (b.amount || 0), 0);
  const remaining = totalBudget - totalSpent;

  const byMonth = allExpenses.reduce((m, e) => {
    if (!e.date) return m;
    const k = new Date(e.date).toLocaleString("default", { month: "short", year: "numeric" });
    m[k] = (m[k] || 0) + (e.amount || 0);
    return m;
  }, {});
  const barData = Object.entries(byMonth).map(([month, amount]) => ({ month, amount }));

  const pieData = budgets.map(b => ({
    name: `${b.icon || ""} ${b.name}`.trim(),
    value: (b.expenses || [])
      .filter(e => !selectedMonth || new Date(e.date).toLocaleString("default", { month: "short", year: "numeric" }) === selectedMonth)
      .reduce((s, e) => s + (e.amount || 0), 0),
  })).filter(d => d.value > 0);

  const recent = [...allExpenses].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 6);

  if (loading) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "60vh" }}>
      <div style={{ fontSize: 14, color: "#9b9b9b" }}>Loading…</div>
    </div>
  );

  return (
    <div style={{ fontFamily: "'Inter', sans-serif" }}>
      {/* Header */}
      <div style={{ marginBottom: 32 }}>
        <div style={{ fontSize: 11, color: "#9b9b9b", letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>Overview</div>
        <h1 style={{ fontSize: 28, fontWeight: 700, color: "#191919", margin: 0, letterSpacing: "-0.03em" }}>
          Good {new Date().getHours() < 12 ? "morning" : new Date().getHours() < 18 ? "afternoon" : "evening"}, {name.split(" ")[0]} 👋
        </h1>
        <p style={{ fontSize: 14, color: "#6b6b6b", marginTop: 6 }}>Here's what's happening with your money.</p>
      </div>

      {/* Stats */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 16, marginBottom: 28 }}>
        <Stat label="Total Spent" value={`RM ${totalSpent.toFixed(2)}`} sub="all time" accent />
        <Stat label="Total Budget" value={`RM ${totalBudget.toFixed(2)}`} sub={`${budgets.length} budgets`} />
        <Stat label="Remaining" value={`RM ${remaining.toFixed(2)}`} sub={remaining >= 0 ? "within limit" : "over budget"} />
        <Stat label="Transactions" value={allExpenses.length} sub="all time" />
      </div>

      {/* Charts */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 20, marginBottom: 24 }}>
        <Card title="Monthly Spending" sub="Click a bar to filter categories">
          {barData.length === 0 ? (
            <div style={{ height: 200, display: "flex", alignItems: "center", justifyContent: "center", color: "#9b9b9b", fontSize: 13 }}>No data yet</div>
          ) : (
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={barData} onClick={e => e?.activeLabel && setSelectedMonth(e.activeLabel === selectedMonth ? null : e.activeLabel)}>
                <XAxis dataKey="month" tick={{ fontSize: 11, fill: "#9b9b9b" }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 11, fill: "#9b9b9b" }} axisLine={false} tickLine={false} tickFormatter={v => `RM${v}`} />
                <Tooltip content={<CustomTooltip />} cursor={{ fill: "#f1f1ef" }} />
                <Bar dataKey="amount" radius={[4, 4, 0, 0]}>
                  {barData.map((entry, i) => (
                    <Cell key={i} fill={entry.month === selectedMonth ? "#2563eb" : "#bfdbfe"} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}
          {selectedMonth && (
            <button onClick={() => setSelectedMonth(null)} style={{ fontSize: 12, color: "#2563eb", background: "none", border: "none", cursor: "pointer", padding: "4px 0", marginTop: 8 }}>
              Clear filter ×
            </button>
          )}
        </Card>

        <Card title="By Category" sub={selectedMonth ? `Filtered: ${selectedMonth}` : "All time"}>
          {pieData.length === 0 ? (
            <div style={{ height: 200, display: "flex", alignItems: "center", justifyContent: "center", color: "#9b9b9b", fontSize: 13 }}>No data yet</div>
          ) : (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={pieData} cx="50%" cy="45%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="value">
                  {pieData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip content={<CustomTooltip />} />
                <Legend iconType="circle" iconSize={8} wrapperStyle={{ fontSize: 12, color: "#6b6b6b" }} />
              </PieChart>
            </ResponsiveContainer>
          )}
        </Card>
      </div>

      {/* Recent Transactions */}
      <Card title="Recent Transactions" sub="Latest 6 expenses across all budgets">
        {recent.length === 0 ? (
          <div style={{ padding: "32px 0", textAlign: "center", color: "#9b9b9b", fontSize: 13 }}>No expenses yet. Add one from the Budgets page.</div>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                {["Description", "Budget", "Amount", "Date"].map(h => (
                  <th key={h} style={{ padding: "8px 12px", fontSize: 11, fontWeight: 600, color: "#9b9b9b", textTransform: "uppercase", letterSpacing: "0.06em", textAlign: h === "Amount" || h === "Date" ? "right" : "left", borderBottom: "1px solid #e8e8e6" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {recent.map(e => (
                <tr key={e.id} style={{ borderBottom: "1px solid #f1f1ef" }}>
                  <td style={{ padding: "12px 12px", fontSize: 14, color: "#191919", fontWeight: 400 }}>{e.description}</td>
                  <td style={{ padding: "12px 12px" }}>
                    <span style={{ background: "#f1f1ef", borderRadius: 5, padding: "3px 8px", fontSize: 12, color: "#374151" }}>
                      {e.budgetIcon} {e.budgetName}
                    </span>
                  </td>
                  <td style={{ padding: "12px 12px", textAlign: "right", fontSize: 14, fontWeight: 600, color: "#191919" }}>RM {(e.amount || 0).toFixed(2)}</td>
                  <td style={{ padding: "12px 12px", textAlign: "right", fontSize: 13, color: "#9b9b9b" }}>
                    {e.date ? new Date(e.date).toLocaleDateString("en-MY", { day: "numeric", month: "short", year: "numeric" }) : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Card>
    </div>
  );
};

export default Dashboard;
